/* Additive appearance migration and map controls. Travel records are never reseeded. */
const avatarModel=window.PPAvatarModel,avatarReturning=Boolean(localStorage.getItem(KEY));
state.profile=avatarModel.migrateAvatarProfile(state.profile||{},avatarReturning);
state.profile.id=state.profile.id||id();
state.profile.mapPreferences={mode:'planning',favoritesOnly:false,previewTransport:'connection',...(state.profile.mapPreferences||{})};
try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}
livingSnapshot=structuredClone(state);window.PPAvatar=state.profile;
let travelerMapMarker=null,lastMapDestination=state.profile.mapPreferences.focusedDestinationId||null,discoveredPlaces=[],discoverySequence=0,avatarDialogOpen=false;
function writeMapPreferences(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Could not save map preferences. Export a backup from Settings.')}}
function applyAppearance(selection,close=true){Object.assign(state.profile,avatarModel.appearanceSelection(selection));state.profile.onboardingCompleted=true;try{save()}catch(error){if(error.storageFailure)return;throw error}if(close){window.PPAvatarUI.close();toast('Your traveler and companion are ready')}}
window.PPAvatarUI={
  close(){window.PPReact.closeAvatarDialog();avatarDialogOpen=false;document.body.classList.remove('appearance-dialog-open');window.dispatchEvent(new Event('appearance-dialog-change'))},
  setup(edit=false){avatarDialogOpen=true;document.body.classList.add('appearance-dialog-open');window.dispatchEvent(new Event('appearance-dialog-change'));window.PPReact.renderAvatarDialog('TravelerSetup',{profile:state.profile,edit,motion:state.profile.ambientMotion!=='off',onClose:()=>this.close(),onComplete:selection=>{applyAppearance(selection);window.PPReact.celebrate({mode:'waving',title:'Welcome to your little world',message:`${avatarModel.characters.find(c=>c.id===selection.selectedCharacterId).shortName} and ${avatarModel.companions.find(c=>c.id===selection.selectedCompanionId).shortName} are ready for the journey.`,kind:'welcome'},state.profile.ambientMotion!=='off');setTimeout(()=>window.PPReact.dismissAchievement(),6500)}})},
  wardrobe(){avatarDialogOpen=true;document.body.classList.add('appearance-dialog-open');window.dispatchEvent(new Event('appearance-dialog-change'));window.PPReact.renderAvatarDialog('WardrobeDialog',{profile:state.profile,motion:state.profile.ambientMotion!=='off',onClose:()=>this.close(),onChange:selection=>applyAppearance(selection,false),onSave:selection=>applyAppearance(selection)})}
};
actions.openWardrobe=()=>window.PPAvatarUI.wardrobe();actions.changeTraveler=()=>window.PPAvatarUI.setup(true);
function visibleMapDestinations(){return state.destinations.filter(d=>(!filters.mapTrip||d.tripId===filters.mapTrip)&&(!filters.mapStatus||d.status===filters.mapStatus)&&(!state.profile.mapPreferences.favoritesOnly||d.favorite))}
function moveMapTraveler(did){const d=visibleMapDestinations().find(d=>d.id===did);if(!d||!travelerMapMarker||d.lat==null||d.lat===''||d.lng==null||d.lng==='')return;travelerMapMarker.setLngLat([Number(d.lng),Number(d.lat)])}
function setupMapTraveler(){travelerMapMarker?.remove();travelerMapMarker=null;if(!map||!state.profile.mapAvatarVisible||!window.maplibregl)return;const places=visibleMapDestinations().filter(d=>d.lat!=null&&d.lat!==''&&d.lng!=null&&d.lng!==''&&Number.isFinite(Number(d.lat))&&Number.isFinite(Number(d.lng))&&Math.abs(Number(d.lat))<=90&&Math.abs(Number(d.lng))<=180),d=places.find(d=>d.id===lastMapDestination)||places.find(d=>/st\.?\s*gallen/i.test(d.name))||places[0];if(!d)return;const node=document.createElement('div');node.className='traveler-map-marker';window.PPReact.renderWidget(node,'CharacterOnMap',{mode:'map',motion:state.profile.ambientMotion!=='off'});travelerMapMarker=new maplibregl.Marker({element:node,anchor:'bottom',offset:[16,-24]}).setLngLat([Number(d.lng),Number(d.lat)]).addTo(map)}
const characterInitMap=initMap;
initMap=function(){mapMarkers=[];characterInitMap();const currentMap=map;if(!currentMap)return;const ready=()=>{if(map!==currentMap)return;setupMapTraveler();document.querySelectorAll('.map-pin').forEach(pin=>{const d=state.destinations.find(d=>d.id===pin.dataset.destinationId);if(state.profile.mapPreferences.favoritesOnly&&!d?.favorite)pin.style.display='none'});};if(currentMap.isStyleLoaded())setTimeout(ready,0);else currentMap.once('style.load',()=>setTimeout(ready,0));currentMap.on('click',async event=>{if(event.originalEvent?.target?.closest?.('.map-pin,.traveler-map-marker,.map-place-sheet'))return;const sequence=++discoverySequence,lat=event.lngLat.lat,lng=event.lngLat.lng;showDiscoveryPlace({name:'Pinned place',country:'',lat,lng,display:`Selected coordinates ${lat.toFixed(4)}, ${lng.toFixed(4)}`});try{const response=await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&addressdetails=1&accept-language=en&lat=${lat}&lon=${lng}`,{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error();const place=await response.json();if(sequence!==discoverySequence||page!=='map')return;showDiscoveryPlace({name:place.name||place.address?.city||place.address?.town||place.address?.village||'Pinned place',country:place.address?.country||'',lat,lng,display:place.display_name||''})}catch{/* Coordinate selection remains usable without lookup. */}})};

const characterShowPlace=showMapPlace;
showMapPlace=function(did){++discoverySequence;characterShowPlace(did);const d=state.destinations.find(d=>d.id===did),sheet=document.querySelector('.map-place-sheet');if(!d||!sheet)return;lastMapDestination=did;state.profile.mapPreferences.focusedDestinationId=did;writeMapPreferences();moveMapTraveler(did);const facts=avatarModel.destinationFacts(state,d,expenseBase),copy=sheet.querySelector('.map-place-copy'),details=document.createElement('div');details.className='map-fact-list';details.innerHTML=`<p><strong>${facts.activities.length} saved activities</strong>${facts.activities.length?` · ${facts.activities.filter(a=>a.status==='completed').length} completed`:''}</p>${facts.activities.slice(0,3).map(a=>`<p>${esc(a.title)} · ${esc(a.time||'Time flexible')}</p>`).join('')}<p><strong>Ledger estimates:</strong> ${money(facts.estimatedExpenses,state.profile.baseCurrency)}${facts.unconverted?` · ${facts.unconverted} await conversion`:''}</p>${Object.keys(facts.activityEstimates).length?`<p><strong>Activity estimates:</strong> ${Object.entries(facts.activityEstimates).map(([currency,n])=>money(n,currency)).join(' + ')}</p>`:''}${d.notes?`<p>${esc(d.notes)}</p>`:''}<small>These estimates come from saved records. They are not confirmed prices.</small>`;copy.querySelector('.sheet-open').before(details);const buttons=document.createElement('div');buttons.className='map-place-actions';buttons.innerHTML=`<button type="button" class="btn small" data-action="favoriteMapPlace" data-id="${did}" aria-pressed="${Boolean(d.favorite)}">${d.favorite?'Saved favorite':'Save favorite'}</button><button type="button" class="btn small" data-action="editDestination" data-id="${did}">Edit place</button>${d.status!=='visited'?`<button type="button" class="btn small primary" data-action="visitMapPlace" data-id="${did}">Mark visited</button>`:`<button type="button" class="btn small" data-action="reopenMapPlace" data-id="${did}">Undo visited</button>`}<button type="button" class="btn small" data-action="deleteDestination" data-id="${did}">Remove place</button>`;copy.append(buttons);bindActions(buttons)};
actions.favoriteMapPlace=({id:did})=>{const d=state.destinations.find(d=>d.id===did);if(!d)return;d.favorite=!d.favorite;save();setTimeout(()=>showMapPlace(did),80)};
actions.visitMapPlace=({id:did})=>{const d=state.destinations.find(d=>d.id===did);if(!d||d.status==='visited')return;d.previousMapStatus=d.status;d.status='visited';save();setTimeout(()=>showMapPlace(did),80)};
actions.reopenMapPlace=({id:did})=>{const d=state.destinations.find(d=>d.id===did);if(!d)return;d.status=d.previousMapStatus||'planned';delete d.previousMapStatus;save();setTimeout(()=>showMapPlace(did),80)};
function discoveryPlace(raw){return {name:raw.name||raw.display_name?.split(',')[0]||'Pinned place',country:raw.address?.country||raw.country||'',lat:Number(raw.lat),lng:Number(raw.lon??raw.lng),display:raw.display_name||raw.display||''}}
function newMapDestination(place,status){const trip=filters.mapTrip||selectedTrip,existing=state.destinations.find(d=>d.tripId===trip&&((d.name.toLowerCase()===place.name.toLowerCase()&&d.country.toLowerCase()===place.country.toLowerCase())||(Math.abs(Number(d.lat)-place.lat)<.0001&&Math.abs(Number(d.lng)-place.lng)<.0001)));if(existing)return showMapPlace(existing.id);destinationForm();const form=document.querySelector('#dialog-form');for(const [name,value] of Object.entries({name:place.name,country:place.country,lat:place.lat,lng:place.lng,status,tripId:trip}))if(form.elements[name])form.elements[name].value=value;toast('Review the place details and save it to your trip')}
function showDiscoveryPlace(place){const shell=document.querySelector('.map-shell');if(!shell)return;shell.querySelector('.map-place-sheet')?.remove();const sheet=document.createElement('section');sheet.className='map-place-sheet discovery-sheet';sheet.setAttribute('aria-label',`${place.name} discovery details`);const relevant=state.destinations.filter(d=>place.country&&d.country.toLowerCase()===place.country.toLowerCase());sheet.innerHTML=`<button type="button" class="sheet-close" aria-label="Close discovery details">×</button>${postcard(place.name==='Pinned place'?place.country:place.name)}<div class="map-place-copy"><span class="pill lav">Discovery · not saved yet</span><h3>${esc(place.name)}</h3><p>${esc(place.country||'Country to review')}</p><small>${esc(place.display)}</small><p class="map-discovery-hint">${place.lat.toFixed(4)}, ${place.lng.toFixed(4)} · Selected map coordinates</p><div class="map-place-actions"><button type="button" class="btn small primary" id="discovery-wishlist">Add to wishlist</button><button type="button" class="btn small" id="discovery-planned">Add to trip</button></div>${relevant.length?`<div class="map-fact-list"><strong>Your saved places in ${esc(place.country)}</strong>${relevant.map(d=>`<p><button class="btn small" data-action="focusMap" data-id="${d.id}">${esc(d.name)} · ${esc(d.status)}</button></p>`).join('')}</div>`:''}<p class="map-discovery-hint">Additions open an editable form. Dates, bookings and visits stay under your control.</p></div>`;shell.append(sheet);sheet.querySelector('.sheet-close').onclick=()=>sheet.remove();sheet.querySelector('#discovery-wishlist').onclick=()=>newMapDestination(place,'wishlist');sheet.querySelector('#discovery-planned').onclick=()=>newMapDestination(place,'planned');bindActions(sheet)}
actions.searchMap=async()=>{const q=document.querySelector('#map-search')?.value.trim();if(!q)return;const sequence=++discoverySequence;toast('Discovering places…');try{const response=await fetch(`https://nominatim.openstreetmap.org/search?format=json&addressdetails=1&accept-language=en&limit=5&q=${encodeURIComponent(q)}`,{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('Search unavailable');const results=await response.json();if(sequence!==discoverySequence||page!=='map')return;if(!results.length)throw Error('No places found. Try a city, country or landmark name.');discoveredPlaces=results.map(discoveryPlace);document.querySelector('.map-discovery-panel')?.remove();const panel=document.createElement('section');panel.className='map-discovery-panel';panel.innerHTML=`<h3>Places to discover</h3>${discoveredPlaces.map((place,i)=>`<div class="discovery-result">${postcard(place.name)}<div><strong>${esc(place.name)}</strong><small>${esc(place.country)} · ${esc(place.display)}</small></div><button type="button" class="btn small" data-place-index="${i}">Explore</button></div>`).join('')}`;document.querySelector('.map-world-controls')?.after(panel);panel.querySelectorAll('[data-place-index]').forEach(button=>button.onclick=()=>{const place=discoveredPlaces[Number(button.dataset.placeIndex)];map?.flyTo({center:[place.lng,place.lat],zoom:8,duration:matchMedia('(prefers-reduced-motion: reduce)').matches?0:600});showDiscoveryPlace(place);document.querySelector('.map-shell')?.scrollIntoView({block:'center',behavior:'auto'})});panel.scrollIntoView({block:'start',behavior:'auto'});}catch(error){toast(error.name==='TimeoutError'?'Search timed out. You can still choose coordinates on the map.':error.message)}};
function addMapWorldControls(){const toolbar=document.querySelector('#map-search')?.closest('.toolbar');if(!toolbar)return;const prefs=state.profile.mapPreferences,controls=document.createElement('section');controls.className='map-world-controls';controls.innerHTML=`<label>World mode<select class="field" id="map-world-mode"><option value="planning" ${prefs.mode==='planning'?'selected':''}>Planning mode</option><option value="preview" ${prefs.mode==='preview'?'selected':''}>Trip preview mode</option><option value="visited" ${prefs.mode==='visited'?'selected':''}>Visited destinations</option></select></label><label><input type="checkbox" id="map-avatar-toggle" ${state.profile.mapAvatarVisible?'checked':''}>Show My Traveler on Map</label><label><input type="checkbox" id="map-favorites-toggle" ${prefs.favoritesOnly?'checked':''}>Favorites only</label><button type="button" class="btn small" data-action="openWardrobe">Wardrobe</button><button type="button" class="btn small" data-action="goTrips">Itinerary →</button>`;toolbar.after(controls);bindActions(controls);controls.querySelector('#map-world-mode').onchange=e=>{prefs.mode=e.target.value;filters.mapStatus=prefs.mode==='visited'?'visited':'';prefs.selectedStatus=filters.mapStatus;save()};controls.querySelector('#map-avatar-toggle').onchange=e=>{state.profile.mapAvatarVisible=e.target.checked;save()};controls.querySelector('#map-favorites-toggle').onchange=e=>{prefs.favoritesOnly=e.target.checked;save()};const note=document.createElement('p');note.className='map-mode-note';note.textContent=prefs.mode==='visited'?'Only destinations you explicitly marked visited are shown.':prefs.mode==='preview'?'Journey movement is a preview of your saved itinerary, not your current physical location.':'Tap a pin for saved details, or tap the map to discover a new place. The traveler is a planning illustration.';controls.after(note);
  const route=document.querySelector('.route-preview');if(route){const select=document.createElement('label');select.className='route-symbol-select';const transport=prefs.previewTransport||'connection';select.innerHTML=`Preview transport symbol<select class="field" id="route-symbol">${option([{id:'connection',name:'Connection · no transport selected'},{id:'plane',name:'Plane'},{id:'train',name:'Train'},{id:'bus',name:'Bus'},{id:'car',name:'Car'}],transport)}</select><small>Approximate connection between saved stops; no verified route or travel time is available.</small>`;route.querySelector('.route-stops').before(select);window.PPMapPreviewTransport=transport==='connection'?'compass':transport;select.querySelector('select').onchange=e=>{prefs.previewTransport=e.target.value;window.PPMapPreviewTransport=e.target.value==='connection'?'compass':e.target.value;writeMapPreferences();if(routeMarker)routeMarker.getElement().innerHTML=pixelIcon(window.PPMapPreviewTransport)};}
  if(prefs.favoritesOnly){const card=[...document.querySelectorAll('.main>.grid.two .card')].find(c=>c.querySelector('h3')?.textContent.includes('Saved places'));if(card){card.querySelectorAll('.list-row,.empty').forEach(row=>row.remove());const places=visibleMapDestinations();card.insertAdjacentHTML('beforeend',places.map(d=>`<div class="list-row"><div><strong>${esc(d.name)}, ${esc(d.country)}</strong><small>${esc(tripName(d.tripId))}</small></div><button class="btn small" data-action="focusMap" data-id="${d.id}">View pin</button></div>`).join('')||'<p>No favorites match these filters. Save a favorite from a destination card.</p>');bindActions(card)}}
}
const avatarEnhance=window.pixelPassportEnhance;
window.pixelPassportEnhance=function(){Object.assign(state.profile,avatarModel.migrateAvatarProfile(state.profile,true));state.profile.mapPreferences={mode:'planning',favoritesOnly:false,previewTransport:'connection',...(state.profile.mapPreferences||{})};travelerMapMarker?.remove();travelerMapMarker=null;window.PPAvatar=state.profile;avatarEnhance();const main=document.querySelector('.main'),toolbar=document.createElement('div');toolbar.className='avatar-toolbar';toolbar.innerHTML=`<span>${esc(avatarModel.characters.find(c=>c.id===state.profile.selectedCharacterId)?.name)} · ${esc(avatarModel.companions.find(c=>c.id===state.profile.selectedCompanionId)?.shortName)}</span><button class="btn small" data-action="openWardrobe">${pixelIcon('jacket')} Wardrobe</button>`;if(page!=='packing'){main.querySelector('.topbar').after(toolbar);bindActions(toolbar);}
  if(page!=='style-guide'){document.querySelectorAll('.sidebar-avatar,.illustrated-page-empty>.action-pose,.quest-companion>.avatar-pose').forEach(sprite=>{const node=document.createElement('span');node.className=sprite.classList.contains('sidebar-avatar')?'sidebar-selected-avatar':'empty-selected-avatar';sprite.replaceWith(node);window.PPReact.renderWidget(node,'TravelerAvatar',{className:node.className==='sidebar-selected-avatar'?'selected-sidebar-avatar':'',mode:page==='tasks'?'happy':'idle',motion:state.profile.ambientMotion!=='off'})})}
  if(page==='settings'){const upload=document.querySelector('#import-file')?.parentElement;if(upload){upload.tabIndex=0;upload.setAttribute('role','button');upload.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();upload.querySelector('input').click()}}}const card=document.createElement('section');card.className='card chosen-profile-card';card.innerHTML=`<h3>${pixelIcon('passport')} Your traveler & companion</h3><div id="settings-avatar-preview"></div><div class="row wrap"><button type="button" class="btn primary" data-action="openWardrobe">Open wardrobe</button><button type="button" class="btn" data-action="changeTraveler">Change traveler & companion</button></div>`;document.querySelector('.settings-list')?.prepend(card);bindActions(card);window.PPReact.renderWidget(card.querySelector('#settings-avatar-preview'),'AvatarPreview',{selection:state.profile,motion:state.profile.ambientMotion!=='off'})}
  if(page==='ski'&&state.profile.selectedOutfitId!=='ski'){const panel=document.createElement('div');panel.className='ski-outfit-suggestion';panel.innerHTML=`<span id="suggested-ski-avatar"></span><div><strong>A warmer outfit for the mountains?</strong><p>Your current outfit stays selected. You can choose skiing clothes in the wardrobe.</p><button class="btn small" data-action="openWardrobe">Try the ski wardrobe</button></div>`;document.querySelector('.living-page-header')?.after(panel);bindActions(panel);window.PPReact.renderWidget(panel.querySelector('#suggested-ski-avatar'),'TravelerAvatar',{outfitId:'ski',motion:state.profile.ambientMotion!=='off',showCompanion:false})}
  if(page==='bookings')document.querySelectorAll('.place-icon').forEach(node=>node.innerHTML=pixelIcon('tickets'));
  if(page==='map')addMapWorldControls();
};
document.addEventListener('change',event=>{if(event.target.id==='map-trip'||event.target.id==='route-trip'){state.profile.mapPreferences.selectedTripId=event.target.value;writeMapPreferences()}if(event.target.id==='map-status'){state.profile.mapPreferences.selectedStatus=event.target.value;if(state.profile.mapPreferences.mode==='visited'&&event.target.value!=='visited')state.profile.mapPreferences.mode='planning';writeMapPreferences()}},true);
filters.mapTrip=state.profile.mapPreferences.selectedTripId||'';filters.mapStatus=state.profile.mapPreferences.mode==='visited'?'visited':state.profile.mapPreferences.selectedStatus||'';
// Initial rendering is performed once, after the packing module has registered.
